(function(root){let controller=null,drag=null,frame=0;const scale=1.35;
function stop(){if(drag?.cancel)drag.cancel();controller?.abort();controller=null;cancelAnimationFrame(frame)}
function hour(t){if(t===1440)return'12 AM';let h=Math.floor(t/60);return(h%12||12)+(h<12?' AM':' PM')}
function bind(api){stop();let host=document.querySelector('#dayCalendar');if(!host)return;controller=new AbortController();let signal=controller.signal,scroller=host.querySelector('.cal-scroll'),plot=host.querySelector('.cal-plot'),blocks=api.getBlocks();
let target=api.scroll??Math.max(0,(Math.min(...blocks.map(b=>Planner.mins(b.start)),660)-35)*scale);scroller.scrollTop=target;scroller.addEventListener('scroll',()=>api.onScroll(scroller.scrollTop),{signal,passive:true});
function live(t){host.querySelector('.cal-live').textContent=t}
function restore(){host.querySelectorAll('.cal-event').forEach(el=>{let b=blocks.find(x=>x.id===el.dataset.eventId);if(b){el.style.top=(Planner.mins(b.start)*scale)+'px';el.style.height=(b.duration*scale)+'px';el.querySelector('.cal-event-time').textContent=b.start+' – '+(Planner.mins(b.start)+b.duration===1440?'24:00':Planner.time(Planner.mins(b.start)+b.duration));el.classList.remove('moving','invalid')}});plot.querySelector('.cal-selection')?.remove();document.body.classList.remove('calendar-dragging');root.SiteMotion?.resume();}
function begin(e,el,mode){if(e.button!==0||e.target.closest('button'))return;let b=blocks.find(x=>x.id===el.dataset.eventId);if(b.type==='fixed')return;let original={start:Planner.mins(b.start),duration:b.duration},originY=e.clientY,originScroll=scroller.scrollTop,moved=false,client=e.clientY,patch={},result=null;el.setPointerCapture(e.pointerId);document.body.classList.add('calendar-dragging');root.SiteMotion?.pause();el.classList.add('moving');
function update(){let delta=Math.round(((client-originY+scroller.scrollTop-originScroll)/scale)/15)*15;let start=original.start,duration=original.duration;if(mode==='end')duration=Math.max(15,Math.min(1440-start,original.duration+delta));else if(mode==='start'){let end=start+duration;start=Math.max(0,Math.min(end-15,start+delta));duration=end-start}else start=Math.max(0,Math.min(1440-duration,start+delta));patch={start:Planner.time(start),duration};result=CalendarModel.adjust(blocks,b.id,patch,false);el.style.top=start*scale+'px';el.style.height=duration*scale+'px';el.classList.toggle('invalid',!result.ok);let label=Planner.time(start)+' – '+(start+duration===1440?'24:00':Planner.time(start+duration));el.querySelector('.cal-event-time').textContent=label;live(result.ok?label+' · '+duration+' minutes':result.error)}
function tick(){let bounds=scroller.getBoundingClientRect();if(client<bounds.top+48)scroller.scrollTop-=Math.min(12,(bounds.top+48-client)/4);else if(client>bounds.bottom-48)scroller.scrollTop+=Math.min(12,(client-bounds.bottom+48)/4);if(moved)update();frame=requestAnimationFrame(tick)}frame=requestAnimationFrame(tick);
function move(v){if(v.pointerId!==e.pointerId)return;client=v.clientY;if(Math.abs(client-originY)>=4)moved=true;if(moved){v.preventDefault();update()}}
function finish(v,cancel=false){if(v.pointerId!==e.pointerId)return;cancelAnimationFrame(frame);el.removeEventListener('pointermove',move);el.removeEventListener('pointerup',up);el.removeEventListener('pointercancel',cancelled);document.removeEventListener('keydown',escape);drag=null;restore();if(cancel){live('Change cancelled.');return}if(!moved){if(!mode)api.edit(b.id);return}if(!result?.ok){el.querySelector('.cal-event-time').textContent=b.start+' – '+Planner.time(original.start+original.duration);api.notify(result?.error||'Choose a free time.');return}api.commit(result.blocks,mode?'Block resized':'Block moved');}
let up=v=>finish(v),cancelled=v=>finish(v,true),escape=v=>{if(v.key==='Escape'){v.preventDefault();finish({pointerId:e.pointerId},true)}};drag={cancel:()=>finish({pointerId:e.pointerId},true)};el.addEventListener('pointermove',move);el.addEventListener('pointerup',up);el.addEventListener('pointercancel',cancelled);document.addEventListener('keydown',escape);}
host.querySelectorAll('.cal-event').forEach(el=>{el.addEventListener('pointerdown',e=>{let handle=e.target.closest('[data-resize]');begin(e,el,handle?.dataset.resize||'')},{signal});el.addEventListener('keydown',e=>{if(e.target!==el)return;let b=blocks.find(x=>x.id===el.dataset.eventId);if(e.key==='Enter'){e.preventDefault();api.edit(b.id);return}if(e.altKey&&['ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();let n=e.key==='ArrowUp'?-15:15;let patch=e.shiftKey?{duration:b.duration+n}:{start:Planner.time(Math.max(0,Math.min(1440-b.duration,Planner.mins(b.start)+n)))};let r=CalendarModel.adjust(blocks,b.id,patch,false);if(r.ok)api.commit(r.blocks,'Calendar updated',b.id);else api.notify(r.error)}},{signal});el.querySelector('[data-cal-edit]')?.addEventListener('click',()=>api.edit(el.dataset.eventId),{signal});});
plot.addEventListener('dblclick',e=>{if(e.target.closest('.cal-event'))return;let at=Math.max(0,Math.min(1410,Math.floor((e.clientY-plot.getBoundingClientRect().top)/scale/15)*15));api.create(Planner.time(at),30)},{signal});
host.querySelector('[data-cal-now]')?.addEventListener('click',()=>{let at=api.nowMinutes();scroller.scrollTo({top:Math.max(0,at*scale-120),behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'})},{signal});
}
function markup(blocks,esc,now){return `<div class="cal-week-strip">${blocks.week}</div><div id="dayCalendar" class="day-calendar"><div class="cal-day-head"><div><span class="mono">${blocks.date}</span><strong>${blocks.weekday}</strong></div><div class="cal-legend"><span>● Focus</span><span>● Rest</span><span>● Fixed</span></div><button class="small" data-cal-now>Now</button></div><div class="cal-scroll" data-lenis-prevent tabindex="0" aria-label="Day calendar, scroll through hours"><div class="cal-hours" style="height:${1440*scale}px">${Array.from({length:24},(_,i)=>`<div class="cal-hour" style="top:${i*60*scale}px"><span>${hour(i*60)}</span></div>`).join('')}<div class="cal-plot" style="height:${1440*scale}px">${blocks.items.map(b=>{let start=Planner.mins(b.start),end=start+b.duration;return `<div role="group" tabindex="0" aria-label="${esc(b.title)}, ${b.start} to ${end===1440?'24:00':Planner.time(end)}, ${b.duration} minutes${b.type==='fixed'?', fixed commitment':''}" class="cal-event ${b.type} ${b.duration<25?'short':''}" data-event-id="${esc(b.id)}" style="top:${start*scale}px;height:${b.duration*scale}px"><span class="cal-resize top" data-resize="start" aria-hidden="true"></span><div class="cal-event-title">${b.type==='fixed'?'⌑ ':''}${esc(b.title)}</div><div class="cal-event-time">${b.start} – ${end===1440?'24:00':Planner.time(end)}</div><button data-cal-edit aria-label="Edit ${esc(b.title)}" title="Edit block">⋯</button>${b.type!=='fixed'?'<span class="cal-resize bottom" data-resize="end" aria-hidden="true"><i></i></span>':''}</div>`}).join('')}${now===null?'':`<div class="cal-now-line" style="top:${now*scale}px"><span></span></div>`}</div></div></div><div class="cal-live" role="status" aria-live="polite">15-minute snap · ${blocks.items.length} blocks</div></div>`}
root.CalendarUI={bind,markup,destroy:stop};
})(window);
